  static JSONObject strictCatalog(byte[] raw)throws Exception{if(raw.length>32*1024*1024)throw new java.io.IOException("network catalog too large");String text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(raw)).toString();JSONTokener tokener=new JSONTokener(text);Object parsed=tokener.nextValue();if(!(parsed instanceof JSONObject)||tokener.nextClean()!=0)throw new java.io.IOException("invalid network catalog document");JSONObject value=(JSONObject)parsed;Object version=value.opt("schema");if(version!=null&&(!(version instanceof Integer||version instanceof Long||version instanceof Short||version instanceof Byte)||((Number)version).longValue()<1||((Number)version).longValue()>2))throw new java.io.IOException("unsupported network catalog schema");for(String key:new String[]{"subscriptions","exits","exitSources"}){if((!key.equals("exitSources")||value.has(key))&&value.optJSONArray(key)==null)throw new java.io.IOException("invalid network catalog list");JSONArray rows=value.optJSONArray(key);if(rows!=null){Set<String> seen=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||row.optString("id").isEmpty()||!seen.add(row.optString("id")))throw new java.io.IOException("invalid network catalog identity");}}}return value;}
